export function calculate(v) {
  if (Object.entries(v).some(([key, value]) => key !== "currency" && (!Number.isFinite(value) || value < 0))) {
    throw new Error("Enter non-negative numbers in every field.");
  }
  if (!v.booking || !v.rental_days || !v.life || !v.available || v.target_margin >= 100) {
    throw new Error("Booking, rental days, recovery life, availability, and margin must be valid.");
  }
  const bookingCosts = v.delivery + v.cleaning + v.damage;
  const ownershipPerDay = v.purchase / v.life;
  const contribution = v.booking - bookingCosts - ownershipPerDay * v.rental_days;
  const minimumPrice = bookingCosts + ownershipPerDay * v.rental_days + v.fixed_monthly / (v.available / v.rental_days);
  const targetPrice = (bookingCosts + ownershipPerDay * v.rental_days) / (1 - v.target_margin / 100);
  // Break-even bookings per month = fixed monthly overhead divided by what
  // one booking actually contributes toward it -- `contribution`, which is
  // already net of this booking's own ownership-cost share. The formula this
  // replaced instead divided by `monthlyContribution` (profit *before*
  // ownership cost) while adding a single booking's ownership cost into the
  // numerator alongside fixed_monthly. That numerator only means "one
  // booking's depreciation," not "this month's depreciation," so it neither
  // scales with the booking count the answer is solving for nor matches the
  // denominator it was divided by -- and the two errors do not cancel out or
  // even point the same direction:
  //   - at the tool's own defaults it overstated break-even by ~0.5% (0.9871
  //     vs. the true 0.9825 bookings/month), and
  //   - once ownership cost exceeds the booking's pre-ownership profit
  //     ($100 booking, $77 booking costs, $26.67 ownership on the defaults'
  //     asset) the old formula still returned a plausible-looking *finite*
  //     count (~4.42) for a booking that in fact never breaks even at any
  //     volume -- every additional booking of that shape loses money once its
  //     own ownership cost is paid, so more volume makes the shortfall worse,
  //     not better.
  // `contribution <= 0` is exactly that second case: this booking does not
  // even cover its own ownership cost before fixed overhead is considered at
  // all, so no number of them ever will.
  const utilization = contribution > 0
    ? v.fixed_monthly / contribution
    : Infinity;
  // Share of the month's available rental days this booking's break-even
  // frequency would consume: `utilization` is a *count* of bookings per
  // month (e.g. 0.98), not a percentage, so it must be scaled by how many
  // days each booking occupies before it means anything as a share of
  // capacity. Computed here, once, so every caller (on-page display and the
  // downloaded snapshot) reads the same number instead of one of them
  // reinventing it and drifting.
  const daysShare = Number.isFinite(utilization) ? (utilization * v.rental_days) / v.available : Infinity;
  return { bookingCosts, ownershipPerDay, contribution, minimumPrice, targetPrice, utilization, daysShare };
}

// The plain-text file "Download quote snapshot" writes to disk. Pulled out
// of app.mjs and given every input as a plain argument (no DOM, no Date.now)
// so the exact string a user saves to their records can be asserted on in a
// test, the same way the on-screen numbers already are.
export function buildSnapshotText(v, r, generatedAt) {
  const utilizationLine = Number.isFinite(r.utilization)
    ? `${r.utilization.toFixed(2)} (${(r.daysShare * 100).toFixed(1)}% of available rental days)`
    : "Not reached";
  return [
    "Equipment Rental Break-Even",
    `Booking price: ${v.currency} ${v.booking}`,
    `Minimum price: ${v.currency} ${r.minimumPrice.toFixed(2)}`,
    `Target-margin price: ${v.currency} ${r.targetPrice.toFixed(2)}`,
    `Break-even bookings per month: ${utilizationLine}`,
    `Generated: ${generatedAt}`,
  ].join("\n");
}

share.mjs.text:
// Shareable link for a rental-booking scenario. Follows the same URL-hash
// convention as this month's other share links across the portfolio:
// nothing is sent to a server, the payload rides in the fragment (never the
// query string a server or Referer header would log), and only a fixed,
// validated shape is accepted back in -- a crafted fragment cannot inject a
// non-numeric cost or an unbounded currency label into the form.
//
// Before this, the only way to hand a priced booking to a partner or
// customer was "Download quote snapshot" (a one-way, read-only text file)
// or naming every field out loud -- there was no way to send the *inputs*
// so the recipient could open them, adjust one assumption, and see the
// result for themselves the way "Save draft" already lets the same browser
// do for itself.

const NUMERIC_FIELDS = [
  "booking",
  "rental_days",
  "delivery",
  "cleaning",
  "damage",
  "purchase",
  "life",
  "fixed_monthly",
  "available",
  "target_margin",
];

function usableNumber(value) {
  const n = Number(value);
  return Number.isFinite(n) && n >= 0 ? n : null;
}

function usableCurrency(value) {
  if (typeof value !== "string") return null;
  const trimmed = value.trim().slice(0, 8);
  return trimmed || null;
}

export function encodeShare(input) {
  const payload = {};
  NUMERIC_FIELDS.forEach((key) => {
    const n = usableNumber(input?.[key]);
    if (n !== null) payload[key] = n;
  });
  const currency = usableCurrency(input?.currency);
  if (currency !== null) payload.currency = currency;
  return encodeURIComponent(JSON.stringify(payload));
}

export function decodeShare(fragment) {
  if (!fragment) return null;
  const raw = String(fragment).replace(/^#/, "");
  if (!raw) return null;
  let parsed;
  try {
    parsed = JSON.parse(decodeURIComponent(raw));
  } catch {
    return null;
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return null;

  const out = {};
  NUMERIC_FIELDS.forEach((key) => {
    const n = usableNumber(parsed[key]);
    if (n !== null) out[key] = n;
  });
  const currency = usableCurrency(parsed.currency);
  if (currency !== null) out.currency = currency;
  if (Object.keys(out).length === 0) return null;
  return out;
}

usage.mjs.text:
// Local, opt-out usage counting for the equipment rental break-even calculator.
//
// Extracted from app.mjs on 2026-09-03. It lived inline there as three
// functions that touched `localStorage` directly, with no guard, and that is a
// real failure rather than a style point: **reading `localStorage` throws**
// when a browser is set to block site data (private windows, "block all
// cookies", some enterprise policies). It does not return null.
//
// What that cost, in app.mjs's own control flow:
//
//   - `usage("calculation")` is called from inside `render()`'s try block, so
//     a visitor with storage blocked got the SecurityError rendered into the
//     results panel *as if it were a calculation error*. The calculator — the
//     entire product — appeared broken.
//   - `showUsage()` ran at module top level, after the event listeners were
//     attached but before `showDrafts()`. A throw there aborted the rest of
//     module evaluation, so the drafts dropdown was never populated, and every
//     later click that recorded an event threw uncaught.
//
// Every sibling venture that keeps its site in `site/` already wraps storage
// this way (`quote-margin-check`, `tender-radar`, `mcp-supply-chain-watch`,
// `shopify-permission-drift`). This is that same shape, and being DOM-free is
// the point: it can be unit-tested against a throwing storage stub, which the
// inline version could not be.
//
// The storage keys are deliberately unchanged (`rental-usage`,
// `rental-usage-off`). Renaming them would silently reset the counts of anyone
// already using the tool and, worse, forget an opt-out someone had chosen —
// re-enabling counting for a visitor who had turned it off.

const KEY = "rental-usage";
const OPT_OUT = "rental-usage-off";

/**
 * The backing store, or null when it cannot be reached.
 *
 * The `try` covers the property access itself, not just the method call: in a
 * browser blocking site data, `localStorage` throws on access rather than
 * being undefined.
 */
function storage() {
  try {
    return typeof localStorage !== "undefined" ? localStorage : null;
  } catch {
    return null;
  }
}

/** Honour the two headers a browser can express this with, and never throw. */
function blocked() {
  try {
    return navigator?.doNotTrack === "1" || navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function enabled() {
  const store = storage();
  if (!store || blocked()) return false;
  try {
    return store.getItem(OPT_OUT) !== "1";
  } catch {
    return false;
  }
}

/** Counts for display. `{}` whenever storage is unreadable or malformed. */
export function counts() {
  const store = storage();
  if (!store) return {};
  try {
    const parsed = JSON.parse(store.getItem(KEY) || "{}");
    // A hand-edited or corrupted value must not reach the caller as a string
    // or an array, which would render as `undefined` counts rather than 0.
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

export function record(event) {
  if (!enabled()) return;
  const store = storage();
  if (!store) return;
  try {
    const data = counts();
    data[event] = (data[event] || 0) + 1;
    store.setItem(KEY, JSON.stringify(data));
  } catch {
    /* best effort: a quota error must never break the calculator */
  }
}

/**
 * Clear the counts and turn counting off.
 *
 * One-way by design, matching the copy the page has always carried ("the
 * button above turns them off"). Returns whether the store accepted it, so the
 * UI can tell the visitor the truth when storage is unavailable rather than
 * claiming it turned something off that it could not reach.
 */
export function clearAndDisable() {
  const store = storage();
  if (!store) return false;
  try {
    store.removeItem(KEY);
    store.setItem(OPT_OUT, "1");
    return true;
  } catch {
    return false;
  }
}
